require "rails_helper"

RSpec.describe Timekeeping::Alerts do
  # "`503 reference_unavailable` over 1% of writes for 5 minutes;"
  # One failure two seconds into a fresh window must not alert before five minutes have passed.
  it "does not raise reference_unavailable from a window that has not yet run its five minutes" do
    window_start = Time.utc(2026, 5, 1, 12, 0, 0)
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 7,
          "windows" => [{ "window_start" => window_start.iso8601, "writes" => 1, "reference_unavailable" => 1,
                          "stale_generation" => 0, "latency_ms_sum" => 20, "latency_ms_buckets" => { "25" => 2 } }] }
      ]
    }
    signals = Timekeeping::Alerts::Signals.new(
      now: window_start + 2, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {},
      write_pause_seconds: nil, stale_generation_outside_handoff_by_company: {}, write_metrics: body,
      prepare_refusals_by_company: nil, unexplained_reconciliation_differences_by_company: nil,
      financial_snapshot_changes_by_company: nil
    )

    names = described_class.evaluate(signals).map { |alert| alert.name.to_s }
    expect(names).not_to include("reference_unavailable")

    later = Timekeeping::Alerts::Signals.new(
      now: window_start + 300, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {},
      write_pause_seconds: nil, stale_generation_outside_handoff_by_company: {}, write_metrics: body,
      prepare_refusals_by_company: nil, unexplained_reconciliation_differences_by_company: nil,
      financial_snapshot_changes_by_company: nil
    )
    expect(described_class.evaluate(later).map { |alert| [alert.name.to_s, alert.company_id] })
      .to include(["reference_unavailable", 7])
  end
end

RSpec.describe Timekeeping::Alerts do
  # "It logs each alert with `company_id`."
  # Company 7 is at 2%, company 8 at 0.5% with far more traffic; pooled they are under 1%.
  it "names only the failing company when a busy healthy company would dilute a pooled rate" do
    window_start = Time.utc(2026, 5, 1, 12, 0, 0)
    window = lambda do |writes, failures|
      { "window_start" => window_start.iso8601, "writes" => writes, "reference_unavailable" => failures,
        "stale_generation" => 0, "latency_ms_sum" => 10 * (writes + failures),
        "latency_ms_buckets" => { "25" => writes + failures } }
    end
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 7, "windows" => [window.call(98, 2)] },
        { "company_id" => 8, "windows" => [window.call(9950, 50)] }
      ]
    }
    signals = Timekeeping::Alerts::Signals.new(
      now: window_start + 300, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {},
      write_pause_seconds: nil, stale_generation_outside_handoff_by_company: {}, write_metrics: body,
      prepare_refusals_by_company: nil, unexplained_reconciliation_differences_by_company: nil,
      financial_snapshot_changes_by_company: nil
    )

    rate_alerts = described_class.evaluate(signals).select { |alert| alert.name.to_s == "reference_unavailable" }
    expect(rate_alerts.map(&:company_id)).to eq([7])
  end
end

